import numpy as np
from numba import stencil, njit

def show(label, fn, *args):
    try:
        res = fn(*args)
        print(label, "=>\n", res)
        return res
    except Exception as e:
        import traceback
        print(label, "=> ERROR:", type(e).__name__, str(e)[:300])
        traceback.print_exc()

# 1D wrap with cval option
@stencil('wrap', cval=-99.0)
def wrap_cval(a):
    return a[-1] + a[0] + a[1]
a = np.arange(5, dtype=np.float64)
r = show("wrap cval (should ignore cval)", wrap_cval, a)
assert np.allclose(r, [5,3,6,9,7])

# 2D wrap
@stencil('wrap')
def wrap2(a):
    return a[-1, 0] + a[0, 0] + a[0, -1]
a2 = np.arange(9, dtype=np.float64).reshape(3,3)
r = show("2D wrap", wrap2, a2)
expected = np.zeros((3,3))
for i in range(3):
    for j in range(3):
        expected[i,j] = a2[(i-1)%3, j] + a2[i, j] + a2[i, (j-1)%3]
print("2D wrap expected:\n", expected)
assert np.allclose(r, expected)

# 2D per-dim mode: wrap on axis0, nearest on axis1
@stencil(mode=('wrap', 'nearest'))
def wrap_nearest(a):
    return a[-1, 1]
r = show("2D per-dim wrap,nearest", wrap_nearest, a2)
expected = np.zeros((3,3))
for i in range(3):
    for j in range(3):
        expected[i,j] = a2[(i-1)%3, min(j+1, 2)]
print("expected:\n", expected)
assert np.allclose(r, expected)

# reflect with cval fallback: neighborhood larger than array
@stencil('reflect', cval=-77.0)
def refl_big(a):
    return a[-5]
a1 = np.arange(3, dtype=np.float64)
r = show("reflect big offset cval", refl_big, a1)
# i=0: idx=-5 -> invalid -> cval; i=1: idx=-4 -> 0; i=2: idx=-3 -> 1
assert np.allclose(r, [-77, 0, 1])

# symmetric with cval fallback
@stencil('symmetric', cval=-55.0)
def sym_big(a):
    return a[-7]
r = show("symmetric big offset cval", sym_big, a1)
# i=0: idx=-7 -> -(-7)-1=6, 6>=3 -> 6-1-6=-1 invalid -> cval
# i=1: idx=-6 -> 5, 5>=3 -> 6-1-5=0 -> a[0]=0
# i=2: idx=-5 -> 4, 4>=3 -> 6-1-4=1 -> a[1]=1
assert np.allclose(r, [-55, 0, 1])

# mode keyword
@stencil(mode='nearest')
def near_kw(a):
    return a[-1]
r = show("nearest keyword", near_kw, a)
assert np.allclose(r, [0,0,1,2,3])

# neighborhood + mode
@stencil('wrap', neighborhood=((-1, 1),))
def wrap_nh(a):
    return a[-1] + a[0] + a[1]
r = show("wrap + neighborhood", wrap_nh, a)
assert np.allclose(r, [5,3,6,9,7])

# standard_indexing + mode
@stencil('wrap', standard_indexing=('b',))
def wrap_std(a, b):
    return a[-1] + b[0]
b = np.array([100.0])
r = show("wrap + standard_indexing", wrap_std, a, b)
assert np.allclose(r, [104,100,101,102,103])

# out= argument
out = np.empty_like(a)
r = show("wrap + out=", lambda x: wrap_nh(x, out=out), a)
assert np.allclose(out, [5,3,6,9,7])

# constant mode still works (regression)
@stencil
def const(a):
    return a[-1] + a[0] + a[1]
r = show("constant regression", const, a)
assert np.allclose(r, [0,3,6,9,0])

@stencil('constant')
def const2(a):
    return a[-1] + a[0] + a[1]
r = show("constant2 regression", const2, a)
assert np.allclose(r, [0,3,6,9,0])

# mode in njit
@stencil('wrap')
def wrap1_jit(a):
    return a[-1] + a[0] + a[1]

@njit
def use_stencil(a):
    return wrap1_jit(a)
r = show("wrap inside njit", use_stencil, a)
assert np.allclose(r, [5,3,6,9,7])

print("ALL OK")
